import json,glob,re
for p in sorted(glob.glob('/tmp/cnm-pierce35/audit/reviewer-b-slice-*.jsonl')):
 print('\n',p)
 for n,l in enumerate(open(p),1):
  x=json.loads(l); d=x['complete_diff']; files=re.findall(r'^diff --git a/(.*?) b/',d,re.M)
  plus=sum(1 for q in d.splitlines() if q.startswith('+') and not q.startswith('+++'))
  minus=sum(1 for q in d.splitlines() if q.startswith('-') and not q.startswith('---'))
