+ rc = BSpiDevice_setMode(dev->bspi, SPI_MODE2);
+ break;
+ case MRAA_SPI_MODE3:
+ rc = BSpiDevice_setMode(dev->bspi, SPI_MODE3);
+ break;
+ default:
+ rc = BSpiDevice_setMode(dev->bspi, SPI_MODE0);
